class Solution:
    def subarraySum(self, nums: list[int], k: int) -> int:
        count = 0
        curr_sum = 0
        prefix = {0: 1}
        for n in nums:
            curr_sum += n
            count += prefix.get(curr_sum - k, 0)
            prefix[curr_sum] = prefix.get(curr_sum, 0) + 1
        return count

