class Solution:
    def maxPathSum(self, nodes: list[int]) -> int:
        max_sum = [float('-inf')]
        def dfs(idx):
            if idx >= len(nodes) or nodes[idx] is None:
                return 0
            left = max(0, dfs(2 * idx + 1))
            right = max(0, dfs(2 * idx + 2))
            max_sum[0] = max(max_sum[0], nodes[idx] + left + right)
            return nodes[idx] + max(left, right)
        dfs(0)
        return max_sum[0]

