class Solution:
    def invertTree(self, nodes: list[int]) -> list[int]:
        if not nodes:
            return []
        tree = list(nodes)
        def invert(idx):
            if idx >= len(tree) or tree[idx] is None:
                return
            left, right = 2 * idx + 1, 2 * idx + 2
            if left < len(tree) and right < len(tree):
                tree[left], tree[right] = tree[right], tree[left]
            invert(left)
            invert(right)
        invert(0)
        return tree

