class Solution:
    def hasPathSum(self, nodes: list[int], targetSum: int) -> bool:
        def dfs(idx, cur_sum):
            if idx >= len(nodes) or nodes[idx] is None:
                return False
            cur_sum += nodes[idx]
            l, r = 2 * idx + 1, 2 * idx + 2
            is_leaf = (l >= len(nodes) or nodes[l] is None) and (r >= len(nodes) or nodes[r] is None)
