from collections import defaultdict
class Solution:
    def findItinerary(self, tickets: list[list[str]]) -> list[str]:
        adj = defaultdict(list)
        tickets.sort(key=lambda x: x[1], reverse=True)
        for src, dst in tickets:
            adj[src].append(dst)
        res = []
        def dfs(src):
            while adj[src]:
                dfs(adj[src].pop())
            res.append(src)
        dfs("JFK")
        return res[::-1]

