class Solution:
    def zigzagLevelOrder(self, nodes: list[int]) -> list[list[int]]:
        if not nodes or nodes[0] is None:
            return []
        res = []
        q = [0]
        left_to_right = True
        while q:
            level = []
            next_q = []
            for idx in q:
                if idx < len(nodes) and nodes[idx] is not None:
                    level.append(nodes[idx])
                    next_q.append(2 * idx + 1)
                    next_q.append(2 * idx + 2)
