class Solution:
    def rob(self, nums: list[int]) -> int:
        if len(nums) == 1:
            return nums[0]
        def helper(n_list):
            r1, r2 = 0, 0
            for n in n_list:
                temp = max(n + r1, r2)
                r1 = r2
                r2 = temp
            return r2
        return max(helper(nums[:-1]), helper(nums[1:]))

