class Solution {
public:
    vector<int> productExceptSelf(vector<int>& nums) {
        int n = nums.size();
        vector<int> res(n, 1);
        int leftProduct = 1;
        for (int i = 0; i < n; ++i) {
            res[i] = leftProduct;
            leftProduct *= nums[i];
        }
        int rightProduct = 1;
        for (int i = n - 1; i >= 0; --i) {
            res[i] *= rightProduct;
            rightProduct *= nums[i];
        }
        return res;
    }
};
// Time Complexity: O(n)
// Space Complexity: O(1) auxiliary space (excluding the output array)

