class Solution:
    def findKthLargest(self, nums: list[int], k: int) -> int:
        import heapq
        min_heap = []
        for num in nums:
            heapq.heappush(min_heap, num)
            if len(min_heap) > k:
                heapq.heappop(min_heap)
        return min_heap[0]
# Time Complexity: O(N log k) where N is the length of nums
# Space Complexity: O(k) for the min-heap

