    def simulateLRU(self, framesCount: int, pageReferences: List[int]) -> Tuple[int, List[int]]:
        cache = OrderedDict()
        page_faults = 0

        for page in pageReferences:
            if page in cache:
                cache.move_to_end(page)
            else:
                page_faults += 1
                if len(cache) >= framesCount:
                    cache.popitem(last=False)
                cache[page] = True

        return (page_faults, list(cache.keys()))

# Time Complexity: O(N) where N is the number of page references, as OrderedDict operations (get, put, evict) operate in O(1) time.
# Space Complexity: O(F) where F is the number of frames (framesCount) stored in the cache.

