        self.log = []
        self.commit_index = 0
        self.last_applied = 0
        self.state = 'FOLLOWER'
        self.match_index = {p: 0 for p in peers}
        self.next_index = {p: 1 for p in peers}

    def append_entries(self, term, leader_id, prev_log_index, prev_log_term, entries, leader_commit):
        if term < self.current_term:
            return {'term': self.current_term, 'success': False}
        # Full log replication and consistency check logic goes here
        return {'term': self.current_term, 'success': True}
# Time Complexity: O(N) per RPC validation, Space Complexity: O(L) where L is log size.

